document.getElementById('proposed').addEventListener('change',e=>{document.getElementById('trial-css').disabled=!e.target.checked;});
const brand=document.getElementById('brand');brand.addEventListener('input',()=>document.documentElement.style.setProperty('--seed-primary',brand.value));document.getElementById('reset-brand').onclick=()=>{document.documentElement.style.removeProperty('--seed-primary');brand.value='#006f94'};
document.getElementById('member-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter||e.target.querySelector('[type=submit]');const status=document.getElementById('form-status');status.textContent='Validating example…';try{await UnionSuiteButtons.run(button,()=>new Promise(resolve=>setTimeout(resolve,900)),'Validating…');status.textContent='Required fields are valid. Example only — nothing saved.'}catch(error){status.textContent='Validation failed. Please try again.'}});document.getElementById('member-form').addEventListener('reset',()=>{document.getElementById('form-status').textContent='Fields reset.'});
document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const el=document.getElementById(b.dataset.copy);try{await navigator.clipboard.writeText(el.textContent);document.getElementById('copy-status').textContent='Copied.'}catch{el.closest('details').open=true;const r=document.createRange();r.selectNodeContents(el);const s=getSelection();s.removeAllRanges();s.addRange(r);document.getElementById('copy-status').textContent='Selected. Press Ctrl+C to copy.'}});

